ent_assets.extraction_status ELSE excluded.extraction_status END,extraction_version=coalesce(excluded.extraction_version,planning_document_assets.extraction_version),error=excluded.error,metadata_json=CASE WHEN excluded.metadata_json='{}' THEN planning_document_assets.metadata_json ELSE excluded.metadata_json END,updated_at=CURRENT_TIMESTAMP;
